using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class FixIdleShieldFront {
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play first");var c=UnityEngine.Object.FindFirstObjectByType<NewPlayerAttackCombo>();var m=c.GetComponent<NewPlayerLocomotion>();var root=UnityEngine.Object.Instantiate(c.transform.Find("NewPlayer Visual").gameObject);root.hideFlags=HideFlags.HideAndDontSave;Vector3 offset;try{root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;c.motions.idle.SampleAnimation(a.gameObject,0);var shield=root.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Shield4");offset=shield.parent.InverseTransformVector(-root.transform.right*.08f);}finally{UnityEngine.Object.DestroyImmediate(root);}Undo.RecordObject(m,"Fix idle shield facing");m.idleShieldRotationOffset=new Vector3(0,0,41.05f);m.idleShieldPositionOffset=offset;EditorUtility.SetDirty(m);EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);return new{rotation=m.idleShieldRotationOffset.ToString(),position=offset.ToString(),outwardDistance=.08f};}
}
